import React, { useCallback, useMemo, useRef, useState } from 'react';
import type * as monaco from 'monaco-editor';
import { Workspace } from '@astral-sh/ruff-wasm-web';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
  ActionButton,
  Button,
  Icon,
  Link,
  Modal,
  ModalBody,
  ModalFooter,
  ModalHeader,
  Text,
} from '@deephaven/components';
import { vsLinkExternal, vsDiscard } from '@deephaven/icons';
import {
  useDebouncedCallback,
  usePromiseFactory,
} from '@deephaven/react-hooks';
import { EMPTY_FUNCTION } from '@deephaven/utils';
import Log from '@deephaven/log';
import Editor from '../notebook/Editor';
import RUFF_DEFAULT_SETTINGS from './RuffDefaultSettings';
import './RuffSettingsModal.scss';
import MonacoProviders from './MonacoProviders';
import MonacoUtils from './MonacoUtils';

interface RuffSettingsModalProps {
  text: string;
  isOpen: boolean;
  onClose: () => void;
  onSave: (value: Record<string, unknown>) => void;
  readOnly?: boolean;
  defaultSettings?: Record<string, unknown>;
}

const log = Log.module('RuffSettingsModal');

const RUFF_SETTINGS_URI = 'inmemory://dh-config/ruff-settings.json';

async function registerRuffSchema(): Promise<void> {
  const { jsonDefaults } = MonacoUtils.getMonaco().languages.json;
  const { schemas = [] } = jsonDefaults.diagnosticsOptions;

  if (!schemas.some(schema => schema.uri === 'json://ruff-schema')) {
    // Register the ruff schema so users get validation and completion
    const { default: ruffSchema } = await import('./ruffSchema');
    jsonDefaults.setDiagnosticsOptions({
      schemas: [
        ...schemas,
        {
          uri: 'json://ruff-schema',
          fileMatch: [RUFF_SETTINGS_URI],
          schema: ruffSchema,
        },
      ],
    });
  }
}

function disposeModel(editor: monaco.editor.IStandaloneCodeEditor): void {
  editor.getModel()?.dispose();
}

async function getRuffVersion(): Promise<string> {
  await MonacoProviders.initRuff();
  return `v${Workspace.version()}`;
}

export default function RuffSettingsModal({
  text,
  isOpen,
  onClose,
  onSave,
  readOnly = false,
  defaultSettings = RUFF_DEFAULT_SETTINGS,
}: RuffSettingsModalProps): React.ReactElement | null {
  const [isValid, setIsValid] = useState(false);
  const [isDefault, setIsDefault] = useState(false);
  const editorRef = useRef<monaco.editor.IStandaloneCodeEditor>();

  const formattedDefaultSettings = useMemo(
    () => JSON.stringify(defaultSettings, null, 2),
    [defaultSettings]
  );

  const { data: ruffVersion } = usePromiseFactory(getRuffVersion);

  const handleClose = useCallback((): void => {
    if (isOpen) {
      onClose();
      editorRef.current = undefined;
    }
  }, [isOpen, onClose]);

  const handleSave = useCallback((): void => {
    if (isOpen) {
      try {
        onSave(JSON.parse(editorRef.current?.getModel()?.getValue() ?? ''));
      } catch {
        // no-op
      }
      handleClose();
    }
  }, [isOpen, handleClose, onSave]);

  const handleReset = useCallback((): void => {
    editorRef.current?.getModel()?.setValue(formattedDefaultSettings);
  }, [formattedDefaultSettings]);

  const validate = useCallback(
    (val: string) => {
      try {
        JSON.parse(val);
        setIsValid(true);
      } catch {
        setIsValid(false);
      }
      setIsDefault(
        editorRef.current?.getModel()?.getValue() === formattedDefaultSettings
      );
    },
    [formattedDefaultSettings]
  );

  const debouncedValidate = useDebouncedCallback(validate, 500, {
    leading: true,
  });

  const onEditorInitialized = useCallback(
    (editor: monaco.editor.IStandaloneCodeEditor): void => {
      const monaco = MonacoUtils.getMonaco();
      editorRef.current = editor;

      // The schema matches the settings by this URI
      const model = monaco.editor.createModel(
        text,
        'json',
        monaco.Uri.parse(RUFF_SETTINGS_URI)
      );
      editor.setModel(model);
      model.onDidChangeContent(() => {
        debouncedValidate(model.getValue());
      });

      registerRuffSchema().catch(log.error);
      debouncedValidate(model.getValue());
    },
    [debouncedValidate, text]
  );

  if (!isOpen) {
    return null;
  }

  return (
    <Modal
      isOpen={isOpen}
      centered
      keyboard
      clickOutside={false}
      toggle={handleClose}
      size="lg"
      className="ruff-settings-modal"
    >
      <ModalHeader closeButton={false}>
        <span className="settings-modal-title mr-auto">
          Ruff {ruffVersion} Settings
        </span>

        <Link href="https://docs.astral.sh/ruff/settings/" target="_blank">
          <Button kind="ghost" onClick={EMPTY_FUNCTION} icon={vsLinkExternal}>
            Settings Docs
          </Button>
        </Link>

        <ActionButton isDisabled={isDefault} onPress={handleReset}>
          <Icon>
            <FontAwesomeIcon icon={vsDiscard} />
          </Icon>
          <Text>Reset to default</Text>
        </ActionButton>
      </ModalHeader>
      <ModalBody style={{ height: '80vh' }}>
        <Editor
          onEditorInitialized={onEditorInitialized}
          onEditorWillDestroy={disposeModel}
          settings={{
            readOnly,
            language: 'json',
            folding: true,
            padding: { bottom: 16 },
            lineNumbers: 'on',
            overviewRulerLanes: 0,
            model: null,
          }}
        />
      </ModalBody>
      <ModalFooter>
        {readOnly ? (
          <Button kind="secondary" data-dismiss="modal" onClick={handleClose}>
            Close
          </Button>
        ) : (
          <>
            <Button kind="secondary" data-dismiss="modal" onClick={handleClose}>
              Cancel
            </Button>
            <Button
              kind="primary"
              data-dismiss="modal"
              tooltip={!isValid ? 'Cannot save invalid JSON' : undefined}
              disabled={!isValid}
              onClick={handleSave}
            >
              Save
            </Button>
          </>
        )}
      </ModalFooter>
    </Modal>
  );
}
